def tile_candidates(grid):
    R,C=len(grid),len(grid[0]); candidates=[]
    for r in range(R-1):
      for c in range(C-1):
        cells={(r+i,c+j) for i,j in product(range(2),repeat=2) if grid[r+i][c+j]==8}
        if len(cells)==4: col=1
        elif len(cells)==3:
          missing=next((i,j) for i,j in product(range(2),repeat=2) if (r+i,c+j) not in cells)
          col={(0,0):2,(1,0):3,(0,1):4,(1,1):5}[missing]
        else: continue
        candidates.append((cells,col,(r,c)))
    return candidates

def exact_covers(grid):
    cells={(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==8}
    cand=tile_candidates(grid)
    out=[]
    def rec(rem, chosen):
      if not rem:
        out.append(chosen); return
      x=min(rem)
      for cellset,col,pos in cand:
        if x in cellset and cellset <= rem:
          rec(rem-cellset,chosen+[(cellset,col,pos)])
    rec(cells,[])
    return out

