def flexible_candidates(grid):
    R,C=len(grid),len(grid[0]); cand=[]
    for r in range(R-1):
      for c in range(C-1):
        box=[(r+i,c+j) for i,j in product(range(2),repeat=2)]
        occ=[x for x in box if grid[x[0]][x[1]]==8]
        if len(occ)==4: cand.append((set(occ),1,(r,c)))
        for miss in box:
          cells=set(box)-{miss}
          if all(grid[x[0]][x[1]]==8 for x in cells):
            i,j=miss[0]-r,miss[1]-c
            col={(0,0):2,(1,0):3,(0,1):4,(1,1):5}[(i,j)]
            cand.append((cells,col,(r,c)))
    return cand

def covers_flex(grid, limit=100000):
    cells={(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==8}
    cand=flexible_candidates(grid)
    by={x:[] for x in cells}
    for i,(cs,col,pos) in enumerate(cand):
      for x in cs: by[x].append(i)
    out=[]
    def rec(rem, chosen):
      if len(out)>=limit:return
      if not rem: out.append(chosen); return
      x=min(rem, key=lambda x: sum(1 for i in by[x] if cand[i][0]<=rem))
      for i in by[x]:
        cs,col,pos=cand[i]
        if cs<=rem: rec(rem-cs,chosen+[i])
    rec(cells,[])
    return out,cand
