def transform(grid):
    rows, cols = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 8}
    candidates = []

    for r in range(rows - 1):
        for c in range(cols - 1):
            box = [(r + dr, c + dc) for dr, dc in product(range(2), repeat=2)]
            present = {p for p in box if grid[p[0]][p[1]] == 8}
            if len(present) == 4:
                candidates.append((present, 1))
            for missing in box:
                cells = set(box) - {missing}
                if cells <= present:
                    dr, dc = missing[0] - r, missing[1] - c
                    color = {(0, 0): 2, (1, 0): 3, (0, 1): 4, (1, 1): 5}[(dr, dc)]
                    candidates.append((cells, color))

    by_cell = {p: [] for p in occupied}
    for i, (cells, _) in enumerate(candidates):
        for p in cells:
            by_cell[p].append(i)

    def search(remaining, chosen):
        if not remaining:
            return chosen
        p = min(remaining, key=lambda q: sum(candidates[i][0] <= remaining for i in by_cell[q]))
        for i in by_cell[p]:
            cells, _ = candidates[i]
            if cells <= remaining:
                result = search(remaining - cells, chosen + [i])
                if result is not None:
                    return result
        return None

    solution = search(occupied, [])
    if solution is None:
        raise ValueError("Input cannot be tiled by 2x2 squares and L-triominoes")

    output = [[0] * cols for _ in range(rows)]
    for i in solution:
        cells, color = candidates[i]
        for r, c in cells:
            output[r][c] = color
    return output
